mapper.select:
SELECT 'EMPLOYEE' "personType" FROM SMT_PARK_BU WHERE COMP_ID=#{company} AND PARK_ID=#{park}
UNION ALL
SELECT CASE COMP_TYPE WHEN 1 THEN 'OUTSOURCED' WHEN 2 THEN 'DISPATCHED' ELSE 'UNKNOWN' END "personType"
FROM SMT_ORGANIZE_RELATION WHERE CAST(ID AS VARCHAR2(64))=#{company} AND PARK_ID=#{park}

SELECT a.ID "mappingId",d.ID "authorityId",d.AREA_TYPE "nature"
FROM SMT_ADMITTANCE_AREA_TYPE_AUTH a LEFT JOIN SMT_DEVICE_AUTHORITY d ON d.ID=a.AUTH_ID AND d.PARK_ID=#{park} AND d.TYPE=1
WHERE a.PARK_ID=#{park} AND a.AUTH_TYPE=1 AND CAST(a.AREA_TYPE_ID AS VARCHAR2(64))=#{area}

SELECT IMAGE FROM SMT_IMAGE WHERE IMAGE_CODE=#{code}
AND PARK_ID IS NULLAND PARK_ID=#{storagePark}
AND IMAGE_TYPE IN #{imageType}

SELECT page.* FROM (SELECT ordered.*,ROWNUM row_number FROM
  (SELECT  FROM () q ORDER BY q."id",q."name") ordered
  WHERE ROWNUM <= #{end}) page WHERE row_number > #{offset}
